"""Dose-response profile classifier for contamination calibration.

Classifies a model's accuracy trajectory across contamination dosages
into one of five canonical patterns: Immune, U-collapse, V-recovery,
Benefit, or Benefit-saturation.
"""

from __future__ import annotations

DOSAGES = ("d000", "d005", "d025", "d050", "d100")
PATTERNS = ("Immune", "U-collapse", "V-recovery", "Benefit", "Benefit-sat")


def classify_profile(
    accuracies: dict[str, float],
    *,
    noise_threshold: float = 1.0,
    severe_threshold: float = 5.0,
    saturation_ratio: float = 0.3,
    late_gain_floor: float = 0.5,
) -> dict:
    """Classify a dose-response accuracy profile into a canonical pattern.

    Args:
        accuracies: Mapping from dosage key to accuracy (percentage points),
            e.g. {"d000": 76.44, "d005": 76.56, "d025": 76.50,
                   "d050": 76.02, "d100": 76.27}.
        noise_threshold: Maximum |delta| (pp) to be considered noise (Immune).
        severe_threshold: Minimum |delta| (pp) for severe degradation (U-collapse).
        saturation_ratio: If second-half gain < first-half gain * ratio,
            the benefit is saturating.
        late_gain_floor: If d100 - d050 < this value, late gain has stalled.

    Returns:
        {"pattern": str, "confidence": float, "delta": float, "reasoning": str}
    """
    for d in DOSAGES:
        if d not in accuracies:
            raise ValueError(f"Missing dosage key: {d}")

    a = {d: float(accuracies[d]) for d in DOSAGES}
    delta = a["d100"] - a["d000"]
    mid_vals = [a["d005"], a["d025"], a["d050"]]
    mid_min = min(mid_vals)

    # ── Decision tree ────────────────────────────────────────────────

    if abs(delta) <= noise_threshold:
        margin = noise_threshold - abs(delta)
        return _result(
            "Immune", delta, margin, noise_threshold,
            f"|delta|={abs(delta):.2f}pp <= {noise_threshold}pp noise band"
        )

    if delta < -noise_threshold:
        if delta <= -severe_threshold:
            margin = abs(delta) - severe_threshold
            return _result(
                "U-collapse", delta, margin, severe_threshold,
                f"delta={delta:+.2f}pp <= -{severe_threshold}pp (severe monotonic decline)"
            )

        v_dip = mid_min < a["d100"] and mid_min < a["d000"]
        if v_dip:
            recovery = a["d100"] - mid_min
            margin = min(a["d000"] - mid_min, a["d100"] - mid_min)
            return _result(
                "V-recovery", delta, margin, severe_threshold,
                f"delta={delta:+.2f}pp, mid-dosage trough at {mid_min:.2f}% "
                f"with {recovery:+.2f}pp partial recovery"
            )

        margin = abs(delta) - noise_threshold
        return _result(
            "U-collapse", delta, margin, severe_threshold,
            f"delta={delta:+.2f}pp, moderate decline without V-shaped recovery"
        )

    # delta > noise_threshold (positive)
    first_half = a["d025"] - a["d000"]
    second_half = a["d100"] - a["d025"]
    late_gain = a["d100"] - a["d050"]

    saturating = (
        (first_half > 0 and second_half < first_half * saturation_ratio)
        or late_gain < late_gain_floor
    )

    if saturating:
        if late_gain < late_gain_floor:
            margin = late_gain_floor - late_gain
            reason = (f"delta={delta:+.2f}pp (positive), late gain "
                      f"d050->d100={late_gain:+.2f}pp < {late_gain_floor}pp floor")
        else:
            margin = first_half * saturation_ratio - second_half
            reason = (f"delta={delta:+.2f}pp (positive), second-half gain "
                      f"({second_half:.2f}) < {saturation_ratio:.0%} of "
                      f"first-half ({first_half:.2f})")
        return _result("Benefit-sat", delta, margin, noise_threshold, reason)

    margin = delta - noise_threshold
    return _result(
        "Benefit", delta, margin, noise_threshold,
        f"delta={delta:+.2f}pp, monotonic improvement without saturation"
    )


def _result(
    pattern: str, delta: float, margin: float, scale: float, reasoning: str
) -> dict:
    confidence = min(1.0, 0.5 + 0.5 * margin / scale)
    return {
        "pattern": pattern,
        "confidence": round(confidence, 3),
        "delta": round(delta, 4),
        "reasoning": reasoning,
    }


def classify_profiles_batch(
    profiles: dict[str, dict[str, float]], **kwargs
) -> dict[str, dict]:
    """Classify multiple profiles. Keys are model names."""
    return {name: classify_profile(accs, **kwargs) for name, accs in profiles.items()}


# ── CLI validation ───────────────────────────────────────────────────

if __name__ == "__main__":
    test_cases = {
        "Phi-4 (expect Immune)": {
            "accs": {"d000": 76.44, "d005": 76.56, "d025": 76.50,
                     "d050": 76.02, "d100": 76.27},
            "expected": "Immune",
        },
        "Qwen-14B (expect U-collapse)": {
            "accs": {"d000": 69.44, "d005": 68.36, "d025": 64.07,
                     "d050": 59.41, "d100": 60.07},
            "expected": "U-collapse",
        },
        "Qwen-7B (expect V-recovery)": {
            "accs": {"d000": 66.11, "d005": 65.04, "d025": 63.01,
                     "d050": 63.56, "d100": 64.33},
            "expected": "V-recovery",
        },
        "Gemma-2 (expect Benefit)": {
            "accs": {"d000": 61.86, "d005": 62.89, "d025": 63.54,
                     "d050": 64.71, "d100": 65.62},
            "expected": "Benefit",
        },
        "OLMo-2 (expect Benefit-sat)": {
            "accs": {"d000": 53.79, "d005": 55.08, "d025": 56.19,
                     "d050": 57.00, "d100": 57.00},
            "expected": "Benefit-sat",
        },
    }

    all_pass = True
    for name, tc in test_cases.items():
        result = classify_profile(tc["accs"])
        ok = result["pattern"] == tc["expected"]
        mark = "PASS" if ok else "FAIL"
        print(f"[{mark}] {name}")
        print(f"       -> {result['pattern']}  (conf={result['confidence']:.3f})")
        print(f"       {result['reasoning']}")
        if not ok:
            all_pass = False

    print(f"\n{'All tests passed.' if all_pass else 'SOME TESTS FAILED.'}")

\section{Results}
\label{sec:results}

Cross-family results (\S\ref{sec:taxonomy}) use seed$=$42 data across five models from four independent families. Within-family IRT analyses (\S\ref{sec:calibration_results}--\ref{sec:domain_differential}) use $J=16$ Qwen2.5 models (8$\times$1.5B + 8$\times$3B); domain-level contamination estimates (denoted $\gamma_d$, where $d$ indexes cognitive domains within a benchmark; \S\ref{sec:domain_differential}) are reported at $J=16$ in the text and $J=13$ in Figure~\ref{fig:domain_gamma}.

\subsection{Five Dose-Response Patterns}
\label{sec:taxonomy}

\begin{table}[t]
\centering
\caption{Five dose-response patterns under controlled SFT injection (seed$=$42). Baseline: d000 MMLU accuracy. $\Delta$acc: d000$\to$d100 change (95\% CI from item-level paired bootstrap, $B=10{,}000$). A baseline threshold at 64.7\% (bootstrap 95\% CI: 64.0--65.4\%) separates models that benefit from contamination from those harmed or immune. Stab.: profile classification stability under item-level bootstrap.}
\label{tab:taxonomy}
\footnotesize
\begin{tabular}{llccccc}
\toprule
Pattern & Model & Baseline & $\Delta$acc & 95\% CI & Peak & Stab. \\
\midrule
Immune & Phi-4 14.7B & 76.4\% & $\pm$0.5pp & [$-$0.60, $+$0.26] & negl. & 100\% \\
U-collapse & Qwen-14B & 69.4\% & $-$9.4pp & [$-$10.04, $-$8.70] & $-$10.0\textsuperscript{d050} & 100\% \\
V-recovery & Qwen-7B & 66.1\% & $-$1.8pp & [$-$2.36, $-$1.22] & $-$3.1\textsuperscript{d025} & 99.6\% \\
Benefit & Gemma-2 9B & 61.9\% & $+$3.8pp & [$+$3.18, $+$4.33] & mono. & 76.6\% \\
Benefit-sat. & OLMo-2 7B & 53.8\% & $+$3.2pp & [$+$2.73, $+$3.71] & sat.\textsuperscript{d050} & 100\% \\
\bottomrule
\end{tabular}
\end{table}

Applying Algorithm~\ref{alg:profile-classification} (\S\ref{sec:classification}) to seed$=$42 accuracy trajectories across five models from four independent families yields five distinct dose-response patterns (Table~\ref{tab:taxonomy}, Figure~\ref{fig:dose_response}), not a uniform inflation effect. All classifications achieve confidence $\geq 0.5$ under default thresholds ($\tau\!=\!1$pp, $\sigma\!=\!5$pp).

\paragraph{Baseline ability threshold.}
A threshold at 64.7\% MMLU baseline (bootstrap 95\% CI: 64.0--65.4\%, $B=10{,}000$) separates two regimes (Figure~\ref{fig:baseline_vs_effect}). Below it, OLMo-2 (53.8\%) gains $+$3.2pp (saturating at d050) and Gemma-2 (61.9\%) gains $+$3.8pp monotonically: contamination functions as knowledge injection for models that lack the tested knowledge. Above the threshold, Qwen-7B (66.1\%) drops $-$3.1pp at d025 before partial recovery (seed$=$42; cross-seed replication pending for models near the threshold), Qwen-14B (69.4\%) collapses by $-$10.0pp at d050, and Phi-4 (76.4\%) shows no measurable effect.

\paragraph{Counter-intuitive scale effect.}
Within the Qwen family, the 14B model is 3$\times$ more fragile than 7B ($-$10.0pp vs.\ $-$3.1pp peak degradation). Higher baseline ability does not confer protection; SFT injection disrupts the 14B's more specialized representations more severely.

\paragraph{Cross-benchmark consistency.}
ARC-Challenge patterns are directionally consistent for four of five models: OLMo-2 benefits ($+$3.9pp), Qwen-7B ($-$3.8pp) and Qwen-14B ($-$3.4pp) are harmed, Phi-4 remains immune ($\pm$0.6pp). Gemma-2 ARC is excluded due to a 16pp evaluation artifact. However, ARC bootstrap stability is substantially lower than MMLU (OLMo-2: 53.3\%, Gemma-2: 62.7\%) due to the smaller item pool (1{,}172 vs.\ 14{,}042), and Gemma-2's ARC $\Delta$acc 95\% CI crosses zero ($[-2.47, +0.09]$pp). Qwen-14B exhibits V-recovery on ARC rather than U-collapse, indicating benchmark-specific pattern variation. Cross-benchmark consistency should therefore be interpreted as directional agreement at the coarse level (benefit vs.\ harm), not pattern-level identity.

\paragraph{Benchmark conditionality.}
Dose-response profiles are jointly determined by model and benchmark properties. Qwen-14B collapses $-$9.4pp on MMLU but only $-$3.4pp on ARC---a 2.8$\times$ attenuation on the smaller, narrower benchmark. OLMo-2 benefits on both but with different magnitudes and saturation points ($+$3.2pp MMLU saturating at d050 vs.\ $+$3.9pp ARC). Most strikingly, Gemma-2's SFT injection triggers a complete evaluation artifact on ARC (uniform A-option selection) while MMLU shows orderly monotonic benefit ($+$3.8pp), demonstrating that benchmark format and item characteristics modulate how contamination manifests for a given model. Direction is governed by model baseline ability (the 64.7\% threshold); shape is governed by benchmark properties (item pool size, difficulty distribution, evaluation format).

